out=[];i=1
def emit(title,rows):
    global i
    out.append(f"\n## {title} ({len(rows)} rows)")
    for p,l,v,c in rows:
        out.append(f"R{i:03d} | page {p} | line {l} | {title} | {v} | {c}"); i+=1
emit("NUMBER",N);emit("ENTITY",EN);emit("FORWARD",FW);emit("DATE",DT);emit("QUALIFIER",QL)
hdr=f"""=== A1 STRUCTURED EXTRACTION ===
source: Poonawalla_Q2FY27_Investor_Presentation.pdf (presentation, Q2 FY27)
fulltext: runs/poonawalla-q2fy27/extracted/poonawalla-presentation-q2fy27-fulltext.md (line numbers are file line numbers incl. header)
row_id_range: R001-R{i-1:03d}
counts: NUMBER {len(N)} | ENTITY {len(EN)} | FORWARD {len(FW)} | DATE {len(DT)} | QUALIFIER {len(QL)}
note: chart-only series with unresolved text-layer mapping are captured as raw labels and marked; no values estimated. Pages 4, 9, 19, 28, 31 are section dividers; pages 38-39 image-only awards.
"""
open("runs/poonawalla-q2fy27/extracted/poonawalla-presentation-q2fy27-structured.md","w",encoding="utf8").write(hdr+"\n".join(out)+"\n")
